  InputGroup,
  InputGroupInput,
  InputGroupAddon,
  InputGroupButton,
} from "@/registry/erbium/ui/input-group";

export default function CopyButtonInputExample() {
  const [value, setValue] = useState("https://erbium.dev");

  return (
    <InputGroup className="w-80">
      <InputGroupInput
        aria-label="URL"
        value={value}
        onChange={(event) => {
          setValue(event.target.value);
        }}
      />
      <InputGroupAddon align="inline-end">
        <CopyButton
          value={value}
          aria-label="Copy URL"
          render={<InputGroupButton variant="embedded" size="icon-xs" />}
        />
      </InputGroupAddon>
    </InputGroup>
